+package com.example;
+
+import static org.junit.jupiter.api.Assertions.*;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.junit.jupiter.params.ParameterizedTest;
+import org.junit.jupiter.params.provider.ValueSource;
+import org.springframework.boot.test.context.SpringBootTest;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+    @BeforeEach
+    void openContact() {
+        navigate(ContactView.class);
+    }
+
+    private TextField name() { return $(TextField.class).withLabel("Name").single(); }
+    private TextField phone() { return $(TextField.class).withLabel("Phone").single(); }
+    private EmailField email() { return $(EmailField.class).single(); }
+    private TextArea message() { return $(TextArea.class).single(); }
+    private Button send() { return $(Button.class).withText("Send").single(); }
+    private Grid<SentMessages.Message> grid() {
+        return (Grid<SentMessages.Message>) $(Grid.class).single();
+    }
+
+    @Test
+    void emptyFormIsEnabledAndShowsAllRequiredErrorsWithoutSending() {
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertTrue(send().isEnabled());
+        assertTrue(name().isEmpty() && email().isEmpty() && phone().isEmpty() && message().isEmpty());
+        test(send()).click();
+        assertTrue(name().isInvalid());
+        assertEquals("Name is required", name().getErrorMessage());
+        assertTrue(email().isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email().getErrorMessage());
+        assertTrue(message().isInvalid());
+        assertEquals("Message is required", message().getErrorMessage());
+        assertFalse(phone().isInvalid());
+        assertTrue(send().isEnabled());
+        assertEquals(0, test(grid()).size());
+        assertFalse($(Notification.class).exists());
+    }
+
+    @Test
+    void invalidEmailAndLongMessagePreserveDraftAndCanBeCorrected() {
+        test(name()).setValue("Ada");
+        test(email()).setValue("invalid-email");
+        test(phone()).setValue("555 0100");
+        test(message()).setValue("x".repeat(501));
+        test(send()).click();
+        assertTrue(email().isInvalid());
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+        assertTrue(message().isInvalid());
+        assertEquals("Message must be at most 500 characters", message().getErrorMessage());
+        assertEquals("Ada", name().getValue());
+        assertEquals("invalid-email", email().getValue());
+        assertEquals("555 0100", phone().getValue());
+        assertEquals(501, message().getValue().length());
+        assertEquals(0, test(grid()).size());
+        assertFalse($(Notification.class).exists());
+        test(email()).clear();
+        test(message()).setValue("x".repeat(500));
+        test(send()).click();
+        assertEquals(1, test(grid()).size());
+        assertFalse(email().isInvalid());
+        assertFalse(message().isInvalid());
+    }
+
+    @Test
+    void enterSendsEmailOnlyAndHistorySurvivesNavigationInNewestFirstOrder() {
+        test(name()).setValue("First");
+        test(email()).setValue("first@example.com");
+        test(message()).setValue("First message");
+        fireShortcut(Key.ENTER);
+        assertTrue(test($(Notification.class).single()).getText().contains("Message sent"));
+        assertFalse(send().isEnabled());
+        assertTrue(name().isEmpty() && email().isEmpty() && phone().isEmpty() && message().isEmpty());
+        test(name()).setValue("Second");
+        assertTrue(send().isEnabled());
+        test(phone()).setValue("555 0101");
+        test(message()).setValue("Second message");
+        test(send()).click();
+        assertEquals("Second", test(grid()).getRow(0).name());
+        assertEquals("First message", test(grid()).getRow(1).message());
+        test($(RouterLink.class).withText("About").single()).click();
+        assertFalse($(Dialog.class).exists());
+        assertEquals("About", $(H1.class).single().getText());
+        navigate(ContactView.class);
+        assertEquals(2, test(grid()).size());
+        assertEquals("Second message", test(grid()).getRow(0).message());
+        assertTrue(send().isEnabled());
+    }
+
+    @ParameterizedTest
+    @ValueSource(ints = {0, 1, 2, 3})
+    void editingAnyFieldReenablesSend(int field) {
+        test(name()).setValue("Ada");
+        test(phone()).setValue("555 0100");
+        test(message()).setValue("Hello");
+        test(send()).click();
+        assertFalse(send().isEnabled());
+        editField(field);
+        assertTrue(send().isEnabled());
+    }
+
+    @ParameterizedTest
+    @ValueSource(ints = {0, 1, 2, 3})
+    void anyDraftFieldGuardsBothLinkAndProgrammaticNavigation(int field) {
+        editField(field);
+        test($(RouterLink.class).single()).click();
+        assertTrue($(Dialog.class).single().isOpened());
+        test($(Button.class).withText("Keep editing").single()).click();
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertFalse(name().isEmpty() && email().isEmpty() && phone().isEmpty() && message().isEmpty());
+        UI.getCurrent().navigate(AboutView.class);
+        assertTrue($(Dialog.class).single().isOpened());
+        test($(Button.class).withText("Discard").single()).click();
+        assertEquals("About", $(H1.class).single().getText());
+        navigate(ContactView.class);
+        assertTrue(name().isEmpty() && email().isEmpty() && phone().isEmpty() && message().isEmpty());
+    }
+
+    private void editField(int field) {
+        switch (field) {
+            case 0 -> test(name()).setValue("Draft name");
+            case 1 -> test(email()).setValue("draft@example.com");
+            case 2 -> test(phone()).setValue("123");
+            case 3 -> test(message()).setValue("Draft message");
+            default -> throw new IllegalArgumentException();
+        }
+    }
